import heapq

def match(orders):
    trades = []
    book_buy = []  # max-heap via (-price, arrival, id)
    book_sell = []  # min-heap via (price, arrival, id)
    orders_info = {}  # id -> [side, price, qty_remaining, arrival, active]
    arrival_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in orders_info:
                orders_info[oid][4] = False
            continue

        oid = o[1]
        side = o[2]

        if typ == 'market':
            qty = o[3]
            price = None
        else:
            price = o[3]
            qty = o[4]

        arrival = arrival_counter
        arrival_counter += 1

        remaining = qty

        if side == 'buy':
            opp_heap = book_sell
        else:
            opp_heap = book_buy

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            opp_id = top[2]
            info = orders_info.get(opp_id)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(opp_heap)
                continue

            opp_price = info[1]

            if typ != 'market':
                if side == 'buy' and opp_price > price:
                    break
                if side == 'sell' and opp_price < price:
                    break

            trade_qty = min(remaining, info[2])
            trade_price = opp_price

            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            info[2] -= trade_qty

            if info[2] == 0:
                info[4] = False
                heapq.heappop(opp_heap)
            # else: partially filled resting order keeps its place (remaining must be 0 now)

        if typ == 'limit' and remaining > 0:
            orders_info[oid] = [side, price, remaining, arrival, True]
            if side == 'buy':
                heapq.heappush(book_buy, (-price, arrival, oid))
            else:
                heapq.heappush(book_sell, (price, arrival, oid))
        else:
            # ioc/market remainder discarded; fully filled limit order needs no resting entry
            pass

    return trades

